toolArgs.file_text:
@page "/settings"
@using sv_89a40f0b2bbc4a2d8d510b237fbb5067.Components.Pages.Settings

@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="SetActiveSection" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: var(--bs-body-bg, #f8f9fa);
    border-right: 1px solid var(--bs-border-color, #dee2e6);
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    transition: background-color 0.2s, border-left 0.2s;
    border-left: 3px solid transparent;
    color: var(--bs-body-color, #212529);
}

.settings-nav-item:hover {
    background-color: rgba(0, 0, 0, 0.04);
}

.settings-nav-item.active {
    background-color: rgba(13, 110, 253, 0.08);
    border-left-color: #0d6efd;
    font-weight: 600;
    color: #0d6efd;
}

.nav-icon {
    font-size: 1.2rem;
}

/* Content area */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

.settings-section h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
}

/* Form controls */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
    font-size: 0.9rem;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 0.375rem;
    font-size: 0.95rem;
    transition: border-color 0.15s;
}

.form-control:focus {
    outline: none;
    border-color: #86b7fe;
    box-shadow: 0 0 0 0.2rem rgba(13, 110, 253, 0.15);
}

select.form-control {
    appearance: auto;
}

/* Buttons */
.btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: opacity 0.15s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background-color: #0d6efd;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background-color: #0b5ed7;
}

.btn-secondary {
    background-color: #6c757d;
    color: white;
}

.btn-secondary:hover:not(:disabled) {
    background-color: #5c636a;
}

.btn-danger {
    background-color: #dc3545;
    color: white;
}

.btn-danger:hover:not(:disabled) {
    background-color: #bb2d3b;
}

.btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.8rem;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Toast messages */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    animation: slideIn 0.3s ease;
}

.toast-success {
    background-color: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast-error {
    background-color: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

@keyframes slideIn {
    from { opacity: 0; transform: translateY(-10px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Toggle switches */
.toggle-group {
    margin-bottom: 1rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.toggle-input {
    width: 2.5rem;
    height: 1.25rem;
    appearance: none;
    background-color: #ccc;
    border-radius: 1rem;
    position: relative;
    cursor: pointer;
    transition: background-color 0.2s;
}

.toggle-input:checked {
    background-color: #0d6efd;
}

.toggle-input::before {
    content: '';
    position: absolute;
    width: 1rem;
    height: 1rem;
    border-radius: 50%;
    background: white;
    top: 0.125rem;
    left: 0.125rem;
    transition: transform 0.2s;
}

.toggle-input:checked::before {
    transform: translateX(1.25rem);
}

/* Avatar */
.avatar-preview {
    margin-bottom: 1.5rem;
    text-align: center;
}

.avatar-image {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #dee2e6;
}

.avatar-placeholder {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    background: #e9ecef;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: #6c757d;
    font-size: 0.85rem;
}

.avatar-url-display {
    margin-top: 0.5rem;
    font-size: 0.8rem;
    color: #6c757d;
    word-break: break-all;
}

/* Channel list */
.channel-list {
    margin-top: 1.5rem;
    margin-bottom: 1rem;
}

.channel-list h3 {
    font-size: 1.1rem;
    margin-bottom: 0.75rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.375rem 0;
    cursor: pointer;
}

/* Expandable Panel */
.expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem 1.25rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
}

.panel-header:hover {
    background: #e9ecef;
}

.panel-content {
    padding: 1.25rem;
    border-top: 1px solid #dee2e6;
}

/* Security items */
.security-item {
    margin-bottom: 1.5rem;
    padding: 1rem;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
}

.security-item-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 0.75rem;
}

.security-item-header h3 {
    margin: 0;
    font-size: 1.1rem;
}

.status-indicator {
    padding: 0.25rem 0.75rem;
    border-radius: 1rem;
    font-size: 0.8rem;
    font-weight: 600;
}

.status-enabled {
    background-color: #d1e7dd;
    color: #0f5132;
}

.status-disabled {
    background-color: #f8d7da;
    color: #842029;
}

.current-session-badge {
    padding: 0.2rem 0.6rem;
    background: #cfe2ff;
    color: #084298;
    border-radius: 0.25rem;
    font-size: 0.8rem;
    font-weight: 500;
}

/* Sessions table */
.sessions-section {
    margin-top: 1.5rem;
}

.sessions-section h3 {
    font-size: 1.1rem;
    margin-bottom: 1rem;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem;
    text-align: left;
    border-bottom: 1px solid #dee2e6;
}

.sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
}

/* Modal */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: white;
    border-radius: 0.5rem;
    padding: 1.5rem;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

.modal-dialog h4 {
    margin-top: 0;
    margin-bottom: 0.75rem;
}

.modal-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.25rem;
    justify-content: flex-end;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.5rem;
    flex-wrap: wrap;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

/* Live Preview */
.live-preview {
    margin-top: 1.5rem;
    padding: 1.25rem;
    border: 2px dashed #dee2e6;
    border-radius: 0.5rem;
    transition: all 0.3s;
}

.live-preview h4 {
    margin-top: 0;
    margin-bottom: 0.75rem;
    font-size: 1rem;
    color: #6c757d;
}

.preview-content {
    transition: all 0.3s;
}

.preview-text {
    margin-bottom: 0.75rem;
}

.preview-button {
    padding: 0.4rem 1rem;
    border: 1px solid #0d6efd;
    background: #0d6efd;
    color: white;
    border-radius: 0.25rem;
    margin-bottom: 0.75rem;
    cursor: default;
}

.preview-card {
    padding: 0.75rem;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    background: #f8f9fa;
}

.preview-card strong {
    display: block;
    margin-bottom: 0.25rem;
}

.preview-card p {
    margin: 0;
    font-size: 0.9em;
}

/* Preview theme variants */
.preview-theme-dark {
    background-color: #1a1a2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-theme-dark .preview-card {
    background: #16213e;
    border-color: #444;
    color: #e0e0e0;
}

.preview-theme-light {
    background-color: #ffffff;
    color: #212529;
}

.preview-theme-system {
    background-color: #f8f9fa;
    color: #212529;
}

/* Preview font sizes */
.preview-font-small .preview-content {
    font-size: 0.8rem;
}

.preview-font-medium .preview-content {
    font-size: 1rem;
}

.preview-font-large .preview-content {
    font-size: 1.2rem;
}

/* Preview compact mode */
.preview-compact {
    padding: 0.75rem;
}

.preview-compact .preview-content {
    line-height: 1.3;
}

.preview-compact .preview-card {
    padding: 0.4rem;
}

/* Loading */
.loading {
    color: #6c757d;
    font-style: italic;
}

